INSERT INTO quiz_questions VALUES(1,1,'Quelle est la première étape de l''accueil d''un adhérent ?','Se présenter et sourire','Lui donner un programme','Vérifier sa carte','L''envoyer sur un tapis','a','Le contact humain est prioritaire');
INSERT INTO quiz_questions VALUES(2,3,'Selon David Goggins, pourquoi est-il facile de réussir aujourd''hui ?','Parce que la plupart des gens sont faibles et manquent de discipline','Parce que la technologie rend tout plus simple','Parce qu''il y a plus d''opportunités qu''avant','Parce que les études sont plus accessibles','a','Goggins affirme que la majorité des gens manquent de ténacité et d''autodiscipline, ce qui rend la réussite accessible à ceux qui en ont.');
INSERT INTO quiz_questions VALUES(3,3,'Qu''est-ce que le ''Cookie Jar'' (pot à cookies) de David Goggins ?','Un régime alimentaire spécial pour les ultramarathons','Un recueil mental de tous ses accomplissements et épreuves surmontées qu''il utilise comme carburant dans les moments difficiles','Un livre de recettes pour sportifs','Une technique de méditation pour se relaxer','b','Le Cookie Jar est une méthode mentale où Goggins rassemble tous ses échecs surmontés et accomplissements pour se rappeler sa force dans les moments de souffrance.');
INSERT INTO quiz_questions VALUES(4,3,'Pourquoi Goggins court-il alors qu''il déteste courir ?','Pour gagner des compétitions et des prix','Parce que son médecin le lui impose','Pour endurcir son esprit et s''entraîner pour la vie, pas pour une course','Pour perdre du poids uniquement','c','Goggins explique qu''il ne s''entraîne pas pour une course mais pour la vie — pour être prêt à affronter n''importe quelle épreuve que la vie lui réservera.');
INSERT INTO quiz_questions VALUES(5,3,'Qu''est-ce que le ''miroir de responsabilité'' inventé par Goggins ?','Un exercice de musculation devant un miroir','Se regarder dans le miroir, identifier ses défauts, les écrire sur des post-it et ne les retirer qu''une fois le problème résolu','Une technique pour améliorer sa posture','Un moyen de se complimenter chaque matin','b','Goggins écrivait ses traits de caractère négatifs sur des post-it collés sur son miroir et ne les retirait que lorsqu''il avait résolu chaque problème.');
INSERT INTO quiz_questions VALUES(6,3,'Lors de sa première course de 160 km, qu''a fait Goggins quand on lui a dit qu''il ne serait pas dans les temps ?','Il a abandonné la course','Il a ralenti pour économiser de l''énergie','Il a couru les 30 derniers kilomètres non-stop malgré des fractures de stress','Il a appelé une ambulance','c','Malgré des fractures de stress, du sang et un état physique catastrophique, Goggins a couru les 30 derniers km non-stop après qu''on lui a dit qu''il ne finirait pas dans les temps.');
INSERT INTO quiz_questions VALUES(7,3,'Selon Goggins, quelle est la différence entre la motivation et ce qui l''anime vraiment ?','La motivation est permanente, l''animation est temporaire','La motivation fluctue en permanence — être animé par un but détruit tout obstacle','Il n''y a aucune différence','La motivation vient des autres, l''animation vient des livres','b','Goggins dit que ''la motivation c''est de la merde'' car elle fluctue. Être véritablement animé par un objectif est bien plus puissant et constant.');
INSERT INTO quiz_questions VALUES(8,115,'Chez MyCoach, la posture de coach est avant tout :','1. Un standard observable, répétable et mesurable, qui doit se voir concrètement en séance','2. Une qualité personnelle qui dépend surtout du charisme naturel du coach','Une manière libre de coacher laissée à l’appréciation de chaque studio','4. Un état d’esprit global qui n’a pas besoin d’être formalisé','a','');
INSERT INTO quiz_questions VALUES(9,116,'Quel est l’objectif principal de la séance test chez MyCoach ?','1. Comprendre le client, poser les bases de l’accompagnement et lui donner envie de se projeter 2. Faire une séance très intense pour impressionner le client 3. Tester un maximum d’exercices pour évaluer toutes ses capacités','2. Faire une séance très intense pour impressionner le client','3. Tester un maximum d’exercices pour évaluer toutes ses capacités','4. Présenter toutes les offres commerciales dès le début de la séance','a','');
INSERT INTO quiz_questions VALUES(10,117,'Quel est l’objectif principal de la pesée client chez MyCoach ?','4. Faire un point rapide sans forcément adapter le programme ensuite','2. Vérifier uniquement le poids pour voir si le client a maigri','3. Comparer les résultats entre clients pour créer de la compétition','1. Suivre la progression, ajuster le plan et renforcer l’engagement du client dans la durée','d','');
INSERT INTO quiz_questions VALUES(14,115,'Quelle attitude principale adopter face à un adhérent ?','Être à l''écoute et exemplaire dans sa posture professionnelle','Rester distant pour préserver son autorité','Monopoliser la parole pour rassurer','Laisser l''adhérent gérer seul sa séance','a','');
INSERT INTO quiz_questions VALUES(15,115,'Que représente le savoir-être MyCoach ?','Ponctualité, tenue et bienveillance avec les adhérents','Soulever le plus lourd possible','La vente agressive de prestations','Le nombre d''heures travaillées','a','');
INSERT INTO quiz_questions VALUES(16,115,'Comment accueillir un adhérent qui entre dans le club ?','Sourire, le nommer si possible et engager la conversation','L''ignorer pour ne pas le déranger','Rester sur son téléphone','Lui présenter directement une offre commerciale','a','');
INSERT INTO quiz_questions VALUES(17,115,'Quelle est la tenue attendue pour un Coach ?','Tenue MyCoach propre et adaptée à la séance','N''importe quelle tenue de sport','Tenue de ville classique','Short et claquettes','a','');
INSERT INTO quiz_questions VALUES(18,116,'Quelle est la 1ʳᵉ étape d''une bonne séance test ?','Découverte du profil et des objectifs du prospect','Mettre un maximum d''intensité dès le début','Présenter tout de suite les tarifs','Démonstration de sa propre force','a','');
INSERT INTO quiz_questions VALUES(19,116,'Que faire à la fin d''une séance test ?','Proposer un plan d''accompagnement et demander l''engagement','Laisser le prospect partir sans proposition','Envoyer un devis par email plus tard','Attendre que le prospect revienne','a','');
INSERT INTO quiz_questions VALUES(20,116,'Que mesure-t-on pendant la séance test ?','Motivation, besoins et capacité du prospect','Maximum de charge soulevée','VO2 max en un test unique','Rien, c''est une démo libre','a','');
INSERT INTO quiz_questions VALUES(21,116,'Quelle erreur éviter en séance test ?','Proposer une séance trop intense ou inadaptée','Écouter le prospect','Prendre des notes sur ses objectifs','Faire une démonstration technique','a','');
INSERT INTO quiz_questions VALUES(22,117,'Quand est-il recommandé de peser un adhérent ?','Le matin, à jeun, après passage aux toilettes','Juste après le déjeuner','Après un entraînement très intense','Le soir après plusieurs repas','a','');
INSERT INTO quiz_questions VALUES(23,117,'Que mesure l''impédancemétrie ?','Masse grasse, masse musculaire et eau','Uniquement le poids total','Le tour de taille','Le niveau d''énergie subjectif','a','');
INSERT INTO quiz_questions VALUES(24,117,'À quelle fréquence peser un adhérent en suivi ?','Toutes les 4 à 6 semaines environ','Tous les jours','Une fois par an','Jamais, c''est inutile','a','');
INSERT INTO quiz_questions VALUES(25,117,'Comment restituer les résultats ?','Expliquer chaque indicateur et positiver les progrès','Annoncer le chiffre sec sans contexte','Insister uniquement sur les points négatifs','Éviter le sujet pour ne pas vexer','a','');
INSERT INTO quiz_questions VALUES(26,118,'À quoi sert la technologie E-sculpt ?','Stimuler les muscles par électromagnétisme','Brûler les calories par la chaleur','Remplacer toute activité physique','Mesurer le taux de masse grasse','a','');
INSERT INTO quiz_questions VALUES(27,118,'Quelle est une contre-indication majeure ?','Grossesse, pacemaker, implants métalliques','Avoir plus de 30 ans','Pratiquer du yoga','Avoir mangé récemment','a','');
INSERT INTO quiz_questions VALUES(28,118,'Durée type d''une séance E-sculpt ?','20 à 30 minutes','5 minutes maximum','2 heures','Une journée entière','a','');
INSERT INTO quiz_questions VALUES(29,118,'À quelle fréquence programmer l''E-sculpt ?','2 à 3 séances/semaine avec récupération','Tous les jours sans pause','Une fois tous les 6 mois','En période de compétition uniquement','a','');
INSERT INTO quiz_questions VALUES(30,119,'Qu''est-ce qu''un suivi spécifique ?','Accompagnement personnalisé selon les objectifs','Plan standard identique pour tous','Une simple séance d''essai','Un abonnement sans contact','a','');
INSERT INTO quiz_questions VALUES(31,119,'Quel outil pour tracer le suivi ?','Fiche client régulièrement mise à jour','Uniquement la mémoire du Coach','Un post-it jeté après la séance','Aucun outil, tout est oral','a','');
INSERT INTO quiz_questions VALUES(32,119,'Tous les combien réévaluer les objectifs ?','Au minimum toutes les 6 à 8 semaines','Jamais','Une fois par an','Seulement si le client le demande','a','');
INSERT INTO quiz_questions VALUES(33,119,'Que doit contenir un bon suivi ?','Objectifs, mesures, plan d''action et étapes clés','Juste le nom du client','Uniquement le numéro d''abonnement','Uniquement ses mensurations','a','');
INSERT INTO quiz_questions VALUES(34,121,'Les 4 coups fondamentaux en boxe anglaise ?','Jab, cross, crochet (hook) et uppercut','Coup de pied, de genou, clé, projection','Lancer, saut, sprint, roulade','Droite, gauche, tête, pied','a','');
INSERT INTO quiz_questions VALUES(35,121,'Position de garde standard ?','Pieds écartés, genoux fléchis, mains hautes près du visage','Bras le long du corps, jambes serrées','Mains dans les poches','Dos courbé, tête baissée','a','');
INSERT INTO quiz_questions VALUES(36,121,'Équipement de protection indispensable ?','Bandes, gants et protège-dents','Chaussures à pointes','Casque de vélo','Lunettes de soleil','a','');
INSERT INTO quiz_questions VALUES(37,121,'Intérêt de la boxe en coaching ?','Cardio, coordination, renforcement et lâcher-prise','Augmenter uniquement la masse grasse','Perdre en coordination','Ralentir le métabolisme','a','');
INSERT INTO quiz_questions VALUES(38,122,'Les 2 mouvements olympiques ?','L''arraché et l''épaulé-jeté','Squat et développé couché','Traction et dips','Presse et rowing','a','');
INSERT INTO quiz_questions VALUES(39,122,'Objectif principal de l''épaulé-jeté ?','Amener la barre au-dessus de la tête en 2 temps','Faire rouler la barre au sol','Pousser la barre avec les bras seuls','Sauter par-dessus la barre','a','');
INSERT INTO quiz_questions VALUES(40,122,'Qualité physique développée ?','La puissance (force × vitesse)','La souplesse passive seule','L''endurance longue durée','Le stretching passif','a','');
INSERT INTO quiz_questions VALUES(41,122,'Par quoi débuter en haltérophilie ?','Technique et mobilité avant de charger','Charger un maximum dès la 1re séance','Ignorer la posture','Supprimer l''échauffement','a','');
INSERT INTO quiz_questions VALUES(42,123,'À quoi sert un témoignage client ?','Renforcer la preuve sociale et la crédibilité','Faire perdre du temps au Coach','Dissuader les prospects','Afficher des photos trompeuses','a','');
INSERT INTO quiz_questions VALUES(43,123,'Quand demander un témoignage ?','Après un résultat concret ou un moment fort','Jamais, c''est intrusif','Uniquement le 1er jour d''abonnement','Au hasard sans contexte','a','');
INSERT INTO quiz_questions VALUES(44,123,'Format de témoignage le plus impactant ?','Vidéo courte avec avant/après et émotion sincère','Texte copié d''un autre client','Témoignage anonyme sans photo','Screenshot de conversation privée','a','');
INSERT INTO quiz_questions VALUES(45,123,'Essentiel à obtenir avant publication ?','Consentement explicite de l''adhérent','Rien, tout est public par défaut','Accord d''un autre adhérent','Autorisation du voisin','a','');
INSERT INTO quiz_questions VALUES(46,124,'Objectif principal du stretching ?','Améliorer la mobilité et aider à la récupération','Gagner en masse musculaire pure','Augmenter la fréquence cardiaque','Remplacer l''entraînement en force','a','');
INSERT INTO quiz_questions VALUES(47,124,'Quand privilégier des étirements passifs longs ?','Après la séance, pour favoriser la récupération','Avant un sprint maximal','Avant une compétition de force','En pleine montée de fréquence cardiaque','a','');
INSERT INTO quiz_questions VALUES(48,124,'Durée typique d''un étirement statique ?','30 secondes à 1 minute environ','Moins de 2 secondes','1 heure minimum','Jusqu''à la douleur intense','a','');
INSERT INTO quiz_questions VALUES(49,124,'Faut-il forcer l''étirement jusqu''à la douleur ?','Non, tension modérée et confortable','Oui, plus ça fait mal mieux c''est','Oui, il faut pleurer à chaque étirement','Non, il ne faut rien sentir du tout','a','');
INSERT INTO quiz_questions VALUES(50,125,'Les 3 macronutriments principaux ?','Protéines, glucides et lipides','Vitamines, minéraux et eau','Sucres, sel et additifs','Alcool, caféine et sucre','a','');
INSERT INTO quiz_questions VALUES(51,125,'Rôle principal des protéines ?','Construction et réparation des tissus','Source principale d''énergie rapide','Hydrater l''organisme','Uniquement donner du goût','a','');
INSERT INTO quiz_questions VALUES(52,125,'Conseiller à qui veut perdre du poids ?','Léger déficit calorique avec alimentation équilibrée','Supprimer tous les aliments','Manger autant de sucres qu''on veut','Ne boire que des sodas light','a','');
INSERT INTO quiz_questions VALUES(53,125,'Le Coach peut-il prescrire un régime ?','Non, il oriente mais ne remplace pas un diététicien','Oui, il remplace un médecin','Oui, avec compléments obligatoires','Non, il doit refuser toute discussion','a','');
INSERT INTO quiz_questions VALUES(54,126,'Principe fondamental du Pilates ?','Gainage profond et respiration contrôlée','Soulever le plus lourd possible','Courir le plus vite possible','Sauts explosifs uniquement','a','');
INSERT INTO quiz_questions VALUES(55,126,'Muscle principalement sollicité ?','Le transverse et l''ensemble du core','Uniquement le biceps','Uniquement le mollet','Aucun muscle n''est sollicité','a','');
INSERT INTO quiz_questions VALUES(56,126,'Respiration à privilégier ?','Respiration costale latérale et contrôlée','Apnée complète du début à la fin','Respiration rapide et saccadée','Expiration forte par le nez uniquement','a','');
INSERT INTO quiz_questions VALUES(57,126,'Bénéfice principal pour l''adhérent ?','Meilleure posture, mobilité et conscience corporelle','Prise de masse musculaire rapide','Hausse immédiate de la VO2 max','Perte ciblée de graisse abdominale','a','');
INSERT INTO quiz_questions VALUES(58,127,'Qu''est-ce que le Reformer Pilates ?','Appareil à chariot et ressorts pour exercices guidés','Un tapis de yoga classique','Un rameur cardio','Un simple banc de musculation','a','');
INSERT INTO quiz_questions VALUES(59,127,'À quoi servent les ressorts du Reformer ?','Fournir une résistance modulable selon le niveau','Faire du bruit pour motiver','Servir d''amortisseur uniquement','Ils ne sont jamais utilisés','a','');
INSERT INTO quiz_questions VALUES(60,127,'Quel niveau peut commencer sur Reformer ?','Tous niveaux avec adaptation des ressorts','Uniquement des athlètes de haut niveau','Uniquement des seniors','Uniquement des danseurs pros','a','');
INSERT INTO quiz_questions VALUES(61,127,'Intérêt principal du Reformer ?','Allier renforcement, mobilité et gainage en décharge','Courir en endurance pure','Porter des charges maximales','Dormir confortablement','a','');
INSERT INTO quiz_questions VALUES(62,129,'Quelle précaution pendant la grossesse ?','Éviter chocs, hyperthermie et décubitus dorsal prolongé','Faire des sauts maximaux à chaque séance','Charger les abdos au maximum','Aucune adaptation nécessaire','a','');
INSERT INTO quiz_questions VALUES(63,129,'Quand reprendre le sport après accouchement ?','Après accord médical et bilan périnéal, progressivement','Le lendemain, en charge lourde','Jamais, le corps est abîmé','Uniquement 5 ans plus tard','a','');
INSERT INTO quiz_questions VALUES(64,129,'Zone à rééduquer en priorité post-natal ?','Périnée et sangle abdominale profonde','Les biceps','Les mollets seulement','La nuque','a','');
INSERT INTO quiz_questions VALUES(65,129,'Exercice à éviter immédiatement après accouchement ?','Crunchs classiques et sauts à impact','Marche tranquille','Respiration abdominale','Étirements doux','a','');
INSERT INTO quiz_questions VALUES(66,130,'Combien de phases dans un cycle menstruel ?','Quatre : menstruelle, folliculaire, ovulatoire, lutéale','Une seule continue','Deux : haute et basse','Dix phases aléatoires','a','');
INSERT INTO quiz_questions VALUES(67,130,'Phase la plus propice à l''intensité ?','La phase folliculaire (avant l''ovulation)','La phase menstruelle uniquement','La phase lutéale tardive','Aucune, jamais d''intensité','a','');
INSERT INTO quiz_questions VALUES(68,130,'Que privilégier pendant la phase menstruelle ?','Séances plus douces, mobilité, gainage léger','Records de force systématiques','Jeûne total et HIIT','Rien, il faut arrêter le sport','a','');
INSERT INTO quiz_questions VALUES(69,130,'Comment intégrer le cycle en programmation ?','Adapter charge et intensité aux sensations','Ignorer le cycle complètement','Faire la même séance chaque jour du mois','Arrêter toute activité 2 semaines sur 4','a','');
INSERT INTO quiz_questions VALUES(70,131,'Enjeu santé majeur à la ménopause ?','Baisse d''œstrogènes, perte osseuse et musculaire','Prise de taille soudaine','Augmentation naturelle de la masse musculaire','Aucun changement hormonal','a','');
INSERT INTO quiz_questions VALUES(71,131,'Entraînement fortement recommandé ?','Renforcement musculaire régulier','Uniquement du cardio lent','Aucun entraînement','Seulement des étirements passifs','a','');
INSERT INTO quiz_questions VALUES(72,131,'Apport nutritionnel clé ?','Protéines suffisantes, calcium et vitamine D','Sucres rapides à chaque repas','Suppression totale des lipides','Jeûne de 48h chaque semaine','a','');
INSERT INTO quiz_questions VALUES(73,131,'Autre bénéfice du sport à la ménopause ?','Meilleur sommeil, humeur et gestion du stress','Perte de toutes les bouffées de chaleur','Retour des règles garanti','Aucun bénéfice','a','');
INSERT INTO quiz_questions VALUES(74,132,'Priorité pour un senior en programmation ?','Mobilité, équilibre et renforcement musculaire','Recherche de 1RM en squat chaque séance','Uniquement du cardio intense','Aucun travail du bas du corps','a','');
INSERT INTO quiz_questions VALUES(75,132,'Risque principal à prévenir ?','Les chutes','La croissance','Le surplus de testostérone','La prise de masse rapide','a','');
INSERT INTO quiz_questions VALUES(76,132,'Fréquence d''entraînement conseillée ?','2 à 3 séances/semaine adaptées','10 séances quotidiennes','Jamais','Une fois par an','a','');
INSERT INTO quiz_questions VALUES(77,132,'Exercice pour travailler l''équilibre ?','Travail unipodal, proprioception, déplacements contrôlés','Sprint maximal','Musculation au sol uniquement','Regarder la télévision','a','');
INSERT INTO quiz_questions VALUES(78,133,'Zone à renforcer pour protéger le bas du dos ?','Le core (abdos profonds, fessiers, lombaires)','Uniquement les biceps','Les mollets seulement','Le cou','a','');
INSERT INTO quiz_questions VALUES(79,133,'Exercice à éviter en cas d''épaule douloureuse ?','Développé derrière la nuque à charge lourde','Rotateurs externes à faible charge','Étirements doux','Mobilité thoracique','a','');
INSERT INTO quiz_questions VALUES(80,133,'Muscles qui stabilisent le genou ?','Quadriceps, ischios et fessiers','Le deltoïde','Le grand dorsal','Le trapèze','a','');
INSERT INTO quiz_questions VALUES(81,133,'Que faire en cas de douleur persistante ?','Orienter vers un professionnel de santé','Ignorer et charger plus lourd','Prescrire des médicaments','Diagnostiquer soi-même la pathologie','a','');
INSERT INTO quiz_questions VALUES(82,134,'Apport protéique cible pour un sportif régulier ?','Environ 1,6 à 2,2 g/kg de poids par jour','0,1 g/kg par jour','10 g/kg par jour','Aucun apport en protéines','a','');
INSERT INTO quiz_questions VALUES(83,134,'Qu''est-ce que le timing nutritionnel ?','Répartir les apports autour des séances','Regarder l''heure en mangeant','Manger uniquement à minuit','Sauter tous les repas','a','');
INSERT INTO quiz_questions VALUES(84,134,'Comment gérer une prise de masse ?','Léger surplus calorique avec protéines suffisantes','Déficit calorique extrême','Alimentation 100% sucrée','Jeûne total','a','');
INSERT INTO quiz_questions VALUES(85,134,'Le Coach peut-il prescrire des compléments médicaux ?','Non, il conseille dans les limites de son champ','Oui, il peut remplacer un médecin','Oui, il vend n''importe quel médicament','Non, il doit interdire tout complément','a','');
INSERT INTO quiz_questions VALUES(86,135,'1ʳᵉ étape de la vente conseil ?','La découverte des besoins du prospect','Annoncer le tarif dès la 1ʳᵉ minute','Signer immédiatement le contrat','Envoyer la facture en premier','a','');
INSERT INTO quiz_questions VALUES(87,135,'Comment traiter une objection ?','Écouter, reformuler, répondre et conclure','Ignorer l''objection','Se fâcher avec le prospect','Couper la conversation','a','');
INSERT INTO quiz_questions VALUES(88,135,'Qu''est-ce qu''un bon closing ?','Proposer l''engagement et accompagner la décision','Ne jamais proposer de vente','Forcer avec pression agressive','Attendre que le prospect décide seul','a','');
INSERT INTO quiz_questions VALUES(89,135,'Posture à adopter en entretien ?','Écoute active, empathie et professionnalisme','Regarder son téléphone','Couper sans cesse la parole','Rester dominant bras croisés','a','');
INSERT INTO quiz_questions VALUES(90,136,'Combien d''adhérents en coaching à 4 ?','4 adhérents coachés simultanément','1 seul adhérent','10 adhérents','Autant que possible','a','');
INSERT INTO quiz_questions VALUES(91,136,'Intérêt du format à 4 ?','Dynamique de groupe tout en restant personnalisé','Réduire le suivi qualité','Occuper plus de machines','Faire attendre les adhérents','a','');
INSERT INTO quiz_questions VALUES(92,136,'Comment organiser une séance à 4 ?','Plan d''atelier avec rotations claires','Improviser au fur et à mesure','Laisser les adhérents s''organiser seuls','Faire la même chose qu''en individuel','a','');
INSERT INTO quiz_questions VALUES(93,136,'Quelle priorité malgré le collectif ?','Sécurité et qualité technique de chacun','Faire le plus de bruit possible','Finir vite la séance','Vendre pendant qu''on coache','a','');
INSERT INTO quiz_questions VALUES(98,138,'Méthode pour prioriser ses tâches ?','La matrice d''Eisenhower (urgent / important)','Faire tout en même temps','Procrastiner toutes les tâches','Attendre qu''on vous dise quoi faire','a','');
INSERT INTO quiz_questions VALUES(99,138,'Bénéfice d''un planning structuré ?','Gagner du temps et réduire la charge mentale','Perdre plus de temps','Augmenter le stress quotidien','Oublier les priorités','a','');
INSERT INTO quiz_questions VALUES(100,138,'Qu''est-ce que le deep work ?','Plages de concentration sans distraction','Travailler 15h d''affilée sans pause','Travailler avec 10 notifications actives','Regarder des vidéos en parallèle','a','');
INSERT INTO quiz_questions VALUES(101,138,'Bonne pratique pour les réunions ?','Objectif clair, durée limitée, décisions actées','Sans ordre du jour, sans limite','Inviter un max de personnes inutilement','Parler sans jamais conclure','a','');
INSERT INTO quiz_questions VALUES(102,139,'Style de communication en management ?','Communication assertive et bienveillante','Agressive et humiliante','Totalement passive sans feedback','Toujours par SMS anonyme','a','');
INSERT INTO quiz_questions VALUES(103,139,'Quand donner un feedback négatif ?','Rapidement, en privé, sur un comportement précis','En public pour humilier','Des mois après les faits','Jamais, tout garder pour soi','a','');
INSERT INTO quiz_questions VALUES(104,139,'Rôle principal d''un manager ?','Faire grandir son équipe et atteindre les objectifs','Imposer sans écouter','Éviter tout contact avec l''équipe','Travailler seul dans son bureau','a','');
INSERT INTO quiz_questions VALUES(105,139,'Pratique qui renforce la confiance d''équipe ?','Rituels réguliers (1:1, point d''équipe, feedback)','Le silence radio complet','Changer d''avis chaque semaine','Annuler tous les échanges','a','');
INSERT INTO quiz_questions VALUES(106,140,'Qu''est-ce qu''un leader inspirant ?','Porteur d''une vision claire qui incarne les valeurs','Celui qui crie le plus fort','Celui qui cache toutes les informations','Celui qui évite de décider','a','');
INSERT INTO quiz_questions VALUES(107,140,'Qu''est-ce que l''exemplarité ?','Faire soi-même ce qu''on demande à son équipe','Demander ce qu''on ne fait pas','Ne jamais prendre de risque','Se cacher des collaborateurs','a','');
INSERT INTO quiz_questions VALUES(108,140,'Comment inspirer son équipe au quotidien ?','Reconnaître les réussites et donner du sens','Critiquer en permanence','Ne jamais parler à l''équipe','Supprimer toutes les réunions','a','');
INSERT INTO quiz_questions VALUES(109,140,'Qualité clé d''un leader ?','Écoute, empathie et clarté de vision','L''arrogance','L''indifférence','Le secret absolu sur tout','a','');
INSERT INTO quiz_questions VALUES(110,150,'Quelle est la 1re étape pour créer un event réussi ?','Définir clairement l''objectif et la cible','Commander les goodies avant tout','Réserver la salle avant d''avoir l''idée','Attendre l''inspiration le jour J','a','');
INSERT INTO quiz_questions VALUES(111,150,'Quel indicateur mesure le succès d''un event ?','Satisfaction des participants et retombées business','Nombre de goodies distribués','La météo du jour','Le nombre de photos prises','a','');
INSERT INTO quiz_questions VALUES(112,150,'Que faire après un évènement ?','Envoyer un suivi, partager les retours et mesurer les résultats','Ne rien faire, passer à autre chose','Supprimer les photos','Refuser tout feedback','a','');
INSERT INTO quiz_questions VALUES(113,150,'Quelle erreur éviter lors de la préparation ?','Négliger la logistique et le rétro-planning','Communiquer suffisamment en amont','Tester la salle avant le jour J','Briefer l''équipe à l''avance','a','');
INSERT INTO quiz_questions VALUES(114,152,'Qu''est-ce qu''un signal faible client ?','Un indice subtil d''un risque de désengagement','Un cri qui alerte immédiatement le coach','Un seul indicateur statistique','Une plainte officielle déposée','a','');
INSERT INTO quiz_questions VALUES(115,152,'Quel signal faible de désengagement côté adhérent ?','Baisse de fréquentation et séances manquées','Achat d''un nouvel équipement','Témoignage positif spontané','Parrainage d''un ami','a','');
INSERT INTO quiz_questions VALUES(116,152,'Comment réagir face à un signal faible ?','Prendre contact rapidement pour comprendre ce qui change','Ignorer en espérant que ça passe','Attendre la résiliation effective','Envoyer directement une offre promotionnelle','a','');
INSERT INTO quiz_questions VALUES(117,152,'Quel outil aide à repérer les signaux faibles ?','Un suivi régulier et un tableau des présences','Ne jamais parler à l''adhérent','Des statistiques annuelles uniquement','Attendre un appel du service client','a','');
INSERT INTO quiz_questions VALUES(120,122,'À l''arraché, comment la barre est-elle amenée au-dessus de la tête ?','En un seul temps, sans arrêt intermédiaire','Toujours en deux temps avec pause à la poitrine','En la poussant avec les bras uniquement','En la tirant assis','a','');
INSERT INTO quiz_questions VALUES(121,122,'Quelle position de réception est caractéristique des mouvements olympiques ?','Debout rigide, jambes tendues','Le squat (accroupi) pour recevoir la charge le plus bas possible','Assis au sol','Un fessier contracté mais buste penché en avant','b','');
INSERT INTO quiz_questions VALUES(122,122,'Quel est l''intérêt principal du tirage haut avant la réception ?','Donner une impulsion verticale maximale à la barre','Faire travailler les biceps isolément','Éviter l''engagement des jambes','Raccourcir le mouvement pour aller plus vite','a','');
INSERT INTO quiz_questions VALUES(123,122,'Pourquoi la mobilité des chevilles et des épaules est-elle cruciale ?','Pour permettre une réception stable sans compensation','Pour pouvoir sauter plus haut','Pour soulever sans échauffement','Elle n''a pas d''importance','a','');
INSERT INTO quiz_questions VALUES(124,122,'Quelle progression pédagogique est la plus appropriée pour un débutant ?','De la barre vide avec technique vers la charge progressive','Charges max dès la première séance','Uniquement du travail avec haltères','Seulement sur machines guidées','a','');
INSERT INTO quiz_questions VALUES(125,122,'Pourquoi utiliser la ceinture de force ?','Pour augmenter la pression intra-abdominale et protéger le rachis sur charges lourdes','Pour remplacer le gainage','Pour ne pas transpirer','Pour le confort esthétique','a','');
INSERT INTO quiz_questions VALUES(126,129,'Quelle précaution principale sur la fréquence cardiaque en grossesse ?','Rester dans une intensité modérée et ne pas dépasser 75-80% de la FCmax','Aller régulièrement en zone max pour stimuler bébé','Supprimer tout cardio','Faire du HIIT tous les jours','a','');
INSERT INTO quiz_questions VALUES(127,129,'Quel exercice est FORTEMENT déconseillé à partir du 2e trimestre ?','Les squats à charge modérée','La marche','Les crunchs sur le dos','La natation','c','');
INSERT INTO quiz_questions VALUES(128,129,'Quel est le principal risque du diastasis recti post-partum ?','Une perte de tonicité abdominale durable et des douleurs lombaires','Une prise de masse musculaire','Une amélioration posturale','Une meilleure digestion','a','');
INSERT INTO quiz_questions VALUES(129,129,'Après un accouchement par voie basse sans complication, la reprise sportive se fait idéalement :','Dès la sortie de la maternité','Après la rééducation du périnée et l''aval du médecin (en général 6-8 semaines)','Au bout de 2 ans','Uniquement en salle de sport','b','');
INSERT INTO quiz_questions VALUES(130,129,'Pourquoi éviter la position décubitus dorsal prolongée après 20 SA ?','Elle comprime la veine cave et peut baisser la tension','Elle favorise le mal de dos uniquement','Elle est plus confortable qu''autre chose','Elle renforce trop les abdos','a','');
INSERT INTO quiz_questions VALUES(131,129,'Quel indicateur incite à stopper immédiatement une séance ?','Saignements, contractions, essoufflement sévère ou vertiges','Une légère sudation','Une montée cardiaque progressive','Une sensation agréable d''effort','a','');
INSERT INTO quiz_questions VALUES(132,124,'Quelle est la différence principale entre stretching actif et passif ?','L''actif utilise la contraction de muscles agonistes, le passif subit un étirement via gravité ou partenaire','Aucune différence','L''actif est plus douloureux par définition','Le passif se fait toujours debout','a','');
INSERT INTO quiz_questions VALUES(133,124,'Quand est-il préférable d''utiliser des étirements passifs longs (> 60s) ?','Juste avant un effort explosif','À distance d''une séance, pour gagner en amplitude à long terme','Pendant un sprint','Jamais, c''est inutile','b','');
INSERT INTO quiz_questions VALUES(134,124,'Quelle technique combine contraction-relâchement pour gagner en amplitude ?','Le PNF (Proprioceptive Neuromuscular Facilitation)','Le crunch','Le saut à la corde','La respiration en apnée','a','');
INSERT INTO quiz_questions VALUES(135,124,'Pourquoi ne pas s''étirer passivement longtemps avant un effort de force ?','Cela peut diminuer temporairement la production de force maximale','C''est interdit par la FFF','Cela bloque la respiration','Il n''y a aucun risque','a','');
INSERT INTO quiz_questions VALUES(136,124,'Quel indicateur signale une mobilité articulaire insuffisante lors d''un squat profond ?','Talons qui décollent et buste qui bascule très en avant','Des genoux stables','Un dos plat','Une respiration profonde','a','');
INSERT INTO quiz_questions VALUES(137,124,'Quelle zone est prioritaire à mobiliser pour un adhérent sédentaire assis toute la journée ?','Hanches (psoas/fléchisseurs) et thoracique','Uniquement le cou','Les doigts','Aucune, la sédentarité n''a aucun impact','a','');
INSERT INTO quiz_questions VALUES(138,134,'Quel apport protéique journalier est recommandé pour un sportif en prise de masse ?','0.4 g/kg/j','1.6 à 2.2 g/kg/j','5 g/kg/j','Aucune importance','b','');
INSERT INTO quiz_questions VALUES(139,134,'Qu''appelle-t-on la fenêtre anabolique post-entraînement ?','Une période de 0-2h propice à la récupération musculaire via apport protéino-glucidique','Un type de régime low-carb','Une pause obligatoire de 6h sans manger','Un moment pour jeûner','a','');
INSERT INTO quiz_questions VALUES(140,134,'Quel est le principal inconvénient d''un déficit calorique trop agressif ?','Perte de masse maigre et chute des performances','Gain de force immédiat','Amélioration systématique de la santé','Pas d''inconvénient connu','a','');
INSERT INTO quiz_questions VALUES(141,134,'Parmi ces conseils, lequel reste dans le périmètre d''un coach sportif (non prescripteur) ?','Prescrire un régime médical','Donner des repères hygiéno-diététiques et orienter vers un diététicien si besoin','Recommander un traitement pour l''hypothyroïdie','Conseiller des compléments nécessitant ordonnance','b','');
INSERT INTO quiz_questions VALUES(142,134,'Quel macronutriment est généralement sous-estimé chez les adhérents qui stagnent en prise de masse ?','Les glucides comme carburant à l''effort et source de récupération','Les lipides trans','L''alcool','L''eau froide uniquement','a','');
INSERT INTO quiz_questions VALUES(143,134,'Pour un adhérent qui ressent des fringales sucrées l''après-midi, le meilleur conseil est :','Répartir les glucides et ajouter protéines et fibres au repas précédent','Supprimer tous les glucides','Ajouter 3 cafés supplémentaires','Sauter le petit-déjeuner','a','');
INSERT INTO quiz_questions VALUES(144,127,'À quoi correspondent les ressorts du Reformer ?','Une résistance progressive et variable pour charger ou décharger le mouvement','Uniquement à du poids libre','À un système d''amortisseurs passifs','À un moteur électrique','a','');
INSERT INTO quiz_questions VALUES(145,127,'Quel principe fondamental du Pilates est particulièrement travaillé sur Reformer ?','Le contrôle du centre (powerhouse) et la fluidité','La puissance explosive maximale','Le travail uniquement en isométrie longue','Aucun principe particulier','a','');
INSERT INTO quiz_questions VALUES(146,127,'Pour un adhérent lombalgique, quel intérêt du Reformer ?','Décharge partielle du poids de corps et renforcement contrôlé','Sollicitation maximale du dos en charge','Interdit aux lombalgiques','Aucun intérêt spécifique','a','');
INSERT INTO quiz_questions VALUES(147,127,'Quelle respiration est privilégiée sur Reformer Pilates ?','Thoracique latérale, expire sur l''effort','Apnée prolongée','Bouche fermée uniquement','Pas de respiration contrôlée','a','');
INSERT INTO quiz_questions VALUES(148,127,'Comment adapter l''intensité au débutant ?','Moins de ressorts (charge plus légère) et amplitude réduite','Tous les ressorts au maximum','Uniquement debout sur le chariot','Sans ressort du tout dès le départ','a','');
INSERT INTO quiz_questions VALUES(149,127,'Quel est le rôle des straps (sangles) sur Reformer ?','Travailler les chaînes des membres supérieurs et inférieurs avec résistance guidée','Attacher l''adhérent à la machine','Régler la hauteur du chariot','Aucun rôle','a','');
INSERT INTO quiz_questions VALUES(150,130,'Quelles sont les 4 phases principales du cycle menstruel ?','Menstruelle, folliculaire, ovulatoire, lutéale','Froide, tiède, chaude, brûlante','Matinale, diurne, nocturne, veillée','Cardio, force, souplesse, repos','a','');
INSERT INTO quiz_questions VALUES(151,130,'Pourquoi la phase folliculaire est-elle propice aux efforts intenses ?','Oestrogènes hauts favorisant la force, la récupération et la tolérance à l''effort','Le corps est déshydraté','La température baisse','Aucune raison hormonale','a','');
INSERT INTO quiz_questions VALUES(152,130,'Quelle adaptation pertinente en phase lutéale tardive (SPM) ?','Baisser l''intensité, privilégier mobilité et cardio modéré','Enchaîner des records personnels','Augmenter l''alcool','Supprimer les protéines','a','');
INSERT INTO quiz_questions VALUES(153,130,'Le syndrome prémenstruel peut impacter la performance par :','Fatigue, rétention d''eau, baisse de motivation et température basale plus haute','Une hausse systématique de la force','Aucun impact jamais','Une meilleure endurance','a','');
INSERT INTO quiz_questions VALUES(154,130,'Quel signe doit alerter le coach en aménorrhée chez une sportive ?','Possible triade de l''athlète (déficit énergétique, aménorrhée, baisse DMO)','Rien, c''est normal','Une amélioration des performances','Une augmentation de la masse grasse','a','');
INSERT INTO quiz_questions VALUES(155,130,'Quelle est la meilleure posture du coach face au cycle de l''adhérente ?','Écouter, adapter et proposer sans imposer','Imposer un programme unique toute l''année','Ignorer totalement le sujet','Remplacer la gynécologue','a','');
INSERT INTO quiz_questions VALUES(156,132,'Quel objectif d''entraînement est prioritaire chez le senior ?','Préserver la masse et la force musculaire (prévention sarcopénie)','Rechercher l''hypertrophie maximale','Monter une charge olympique à chaque séance','Ne faire que des étirements passifs','a','');
INSERT INTO quiz_questions VALUES(157,132,'Quelle capacité travailler en priorité pour prévenir les chutes ?','L''équilibre proprioceptif et la force des jambes','Le sprint en ligne droite','La souplesse des doigts uniquement','La rétention respiratoire','a','');
INSERT INTO quiz_questions VALUES(158,132,'Quelle fréquence hebdomadaire est recommandée en renforcement chez le senior ?','2 à 3 fois par semaine avec charges modérées et récupération suffisante','7 fois par jour','Une fois par trimestre','Jamais','a','');
INSERT INTO quiz_questions VALUES(159,132,'Exercice fonctionnel particulièrement pertinent chez le senior ?','Se relever d''une chaise (squat assis-debout)','Snatch à 1RM','Burpees avec saut max','Sprint 100m chronométré','a','');
INSERT INTO quiz_questions VALUES(160,132,'Quelle vigilance face à l''hypertension ou trouble cardio chez le senior ?','Exiger l''aval médical, surveiller signes d''essoufflement et éviter les apnées (Valsalva)','Aucune vigilance nécessaire','Pousser au maximum à chaque séance','Interdire toute activité physique','a','');
INSERT INTO quiz_questions VALUES(161,132,'Comment adapter la récupération entre séries chez un senior ?','Plutôt plus longue que chez un jeune (2-3 min) pour tolérance cardio-vasculaire','Plus courte systématiquement','Jamais de repos','Selon la météo','a','');
INSERT INTO quiz_questions VALUES(162,135,'Quel est le rôle principal de la phase de découverte client ?','Identifier besoins, motivations et freins avant toute proposition','Vendre le plus cher possible immédiatement','Éviter les questions','Couper la parole du prospect','a','');
INSERT INTO quiz_questions VALUES(163,135,'Que signifie la technique du SONCAS ?','Une grille d''analyse des motivations d''achat (Sécurité, Orgueil, Nouveauté, Confort, Argent, Sympathie)','Un logiciel de caisse','Un type de remise commerciale','Une méthode d''entretien annuel','a','');
INSERT INTO quiz_questions VALUES(164,135,'Face à l''objection ''C''est trop cher'', la meilleure réponse est :','Reformuler, comparer à la valeur et chiffrer le retour perçu','Baisser immédiatement de 50%','Dire ''vous n''avez pas les moyens ?''','Raccrocher','a','');
INSERT INTO quiz_questions VALUES(165,135,'Qu''est-ce que le closing assumé ?','Proposer l''engagement au bon moment, de façon claire et directive','Attendre que le client parle en premier','Forcer la vente par pression','Fermer la boutique à la fin de la journée','a','');
INSERT INTO quiz_questions VALUES(166,135,'Quel indicateur clé suit la performance commerciale d''un coach ?','Taux de conversion (visites/signatures) et LTV','Le nombre de cafés bus','La température extérieure','Le nombre de posts Instagram','a','');
INSERT INTO quiz_questions VALUES(167,135,'Quelle attitude renforce la confiance en entretien de vente ?','L''écoute active, la reformulation et la transparence sur l''offre','Parler sans pause pendant 30 minutes','Utiliser un jargon technique incompréhensible','Éviter le contact visuel','a','');
INSERT INTO quiz_questions VALUES(168,133,'Quel muscle stabilisateur de l''épaule est souvent responsable des tendinopathies ?','La coiffe des rotateurs (sus-épineux notamment)','Le grand droit de l''abdomen','Le quadriceps','Le tibial antérieur','a','');
INSERT INTO quiz_questions VALUES(169,133,'En cas de douleur lombaire non traumatique, quel réflexe de coaching ?','Favoriser le mouvement adapté (mobilité, gainage) plutôt que l''immobilisation prolongée','Imposer 3 mois de repos strict','Charger immédiatement en squat lourd','Masser avec forte pression','a','');
INSERT INTO quiz_questions VALUES(170,133,'Quel exercice renforce le vaste médial pour protéger le genou ?','Fentes contrôlées avec genou aligné sur le 2e orteil','Genoux en valgus profond','Rotation rapide du genou','Lever de jambe tendue debout uniquement','a','');
INSERT INTO quiz_questions VALUES(171,133,'Quel test simple évalue la mobilité de l''épaule ?','Le scratch test d''Apley (main dans le dos)','Le saut vertical','Le 1RM au développé couché','La planche 2 minutes','a','');
INSERT INTO quiz_questions VALUES(172,133,'Que faire si la douleur est vive et persistante malgré l''adaptation ?','Orienter vers un médecin ou kiné, ne pas se substituer au diagnostic médical','Continuer à charger','Injecter soi-même un anti-inflammatoire','Ignorer la douleur','a','');
INSERT INTO quiz_questions VALUES(173,133,'Quel principe de programmation respecte une zone fragile ?','Progressivité, variation et charge relative sous-maximale','Toujours aller au maximum','Sauter systématiquement les échauffements','Ne jamais solliciter la zone','a','');
INSERT INTO quiz_questions VALUES(174,139,'Qu''est-ce qu''un feedback ''SBI'' ?','Situation, Behavior (comportement), Impact : une structure de retour clair et factuel','Une méthode de recrutement','Un outil de comptabilité','Une posture de yoga','a','');
INSERT INTO quiz_questions VALUES(175,139,'Quel style de communication est le plus efficace pour désamorcer un conflit ?','L''assertivité : dire clairement sans agresser ni se soumettre','L''agressivité','La fuite','La manipulation','a','');
INSERT INTO quiz_questions VALUES(176,139,'Que signifie manager par la confiance ?','Déléguer, responsabiliser et contrôler le résultat, pas le processus','Surveiller chaque action en temps réel','Laisser faire totalement sans cadre','Ne jamais déléguer','a','');
INSERT INTO quiz_questions VALUES(177,139,'Pourquoi l''écoute active est-elle clé en management ?','Elle permet de comprendre les réels besoins/freins et d''adapter sa décision','Elle fait gagner du temps en coupant la parole','Elle évite d''avoir à décider','Aucun intérêt','a','');
INSERT INTO quiz_questions VALUES(178,139,'Quelle est la bonne fréquence de 1:1 avec un collaborateur ?','Régulière (souvent bi-mensuelle ou mensuelle), structurée et dédiée','Une fois tous les 5 ans','Uniquement en cas de problème grave','Toutes les heures','a','');
INSERT INTO quiz_questions VALUES(179,139,'Que faire si un coach de l''équipe sous-performe régulièrement ?','Objectiver, donner feedback SMART, proposer un plan d''accompagnement avec échéance','L''ignorer et espérer que ça passe','Le critiquer publiquement','Le licencier sans dialogue','a','');
INSERT INTO quiz_questions VALUES(186,140,'Qu''est-ce qui distingue le manager du leader ?','Le manager gère l''opérationnel, le leader donne du sens et une vision','Rien du tout, c''est synonyme','Le leader est forcément plus âgé','Seul le leader a un bureau','a','');
INSERT INTO quiz_questions VALUES(187,140,'Pourquoi la posture d''exemplarité est-elle centrale pour un leader ?','Parce qu''elle crédibilise le discours et entraîne l''adhésion par le comportement visible','Parce qu''elle autorise à tout exiger sans rien faire','Parce qu''elle est facultative','Elle n''a aucun impact','a','');
INSERT INTO quiz_questions VALUES(188,140,'Qu''est-ce que la vision d''équipe ?','Un cap clair, inspirant et partagé qui donne du sens aux actions quotidiennes','Un simple planning hebdo','Une liste de règles','Un secret à garder','a','');
INSERT INTO quiz_questions VALUES(189,140,'Quel levier pour développer l''autonomie de l''équipe ?','Déléguer progressivement en clarifiant les résultats attendus, pas le comment','Décider seul de tout','Annuler toutes les décisions prises par l''équipe','Tout contrôler minute par minute','a','');
INSERT INTO quiz_questions VALUES(190,140,'Comment gérer ses propres émotions en tant que leader ?','Nommer, réguler et choisir la réponse appropriée (intelligence émotionnelle)','Les masquer en permanence','Exploser sur l''équipe','Les ignorer','a','');
INSERT INTO quiz_questions VALUES(191,140,'Quelle pratique régulière développe le leadership ?','La rétrospective personnelle et le feedback à 360°','Éviter tout retour extérieur','Ne jamais se remettre en question','Travailler en silo absolu','a','');
INSERT INTO quiz_questions VALUES(192,115,'Un adhérent arrive visiblement contrarié, quelle est la meilleure posture ?','Accueillir son émotion, reformuler sans juger et adapter la séance','Faire comme si de rien n''était','Lui reprocher son attitude','Annuler la séance sans explication','a','');
INSERT INTO quiz_questions VALUES(193,115,'Quelle attitude incarne le savoir-être MyCoach ?','Bienveillance exigeante : exigeant sur le cadre, bienveillant dans la relation','Laxisme total','Autoritarisme permanent','Indifférence','a','');
INSERT INTO quiz_questions VALUES(194,115,'Comment gérer une remarque négative publique d''un adhérent ?','Prendre à part, écouter en privé puis proposer une solution','Répondre agressivement devant tout le monde','Feindre de ne pas avoir entendu','Exclure l''adhérent','a','');
INSERT INTO quiz_questions VALUES(195,115,'Quel est le rôle du coach face à un adhérent qui stagne ?','Repositionner les objectifs, revoir programme et hygiène de vie','Le culpabiliser systématiquement','L''ignorer dans le club','Lui vendre 3 forfaits supplémentaires','a','');
INSERT INTO quiz_questions VALUES(196,115,'Quelle posture favorise la fidélisation long terme ?','La régularité dans le suivi et la personnalisation de la relation','Des promotions uniquement','Le renouvellement permanent des coachs','Aucune interaction entre les séances','a','');
INSERT INTO quiz_questions VALUES(197,116,'Quel est le vrai ''produit'' vendu lors d''une séance test ?','Un projet, une méthode et une relation de confiance','Un abonnement salle sans accompagnement','Un t-shirt','Une seule séance isolée','a','');
INSERT INTO quiz_questions VALUES(198,116,'Quel ordre est le plus efficace lors de la séance test ?','Accueil, découverte, démonstration, projection, proposition','Proposition en premier, avant toute discussion','Démo avant l''accueil','Juste la facturation','a','');
INSERT INTO quiz_questions VALUES(199,116,'Quelle information essentielle recueillir en découverte ?','Le ''pourquoi profond'' de l''adhérent et ses contraintes concrètes','Son numéro de sécurité sociale','Le modèle de sa voiture','Son opinion politique','a','');
INSERT INTO quiz_questions VALUES(200,116,'Erreur classique en séance test à éviter :','Charger techniquement la séance au détriment de la relation et du projet','Écouter l''adhérent','Faire une démo simple','Conclure la séance','a','');
INSERT INTO quiz_questions VALUES(201,116,'Comment conclure une séance test ?','Récapituler, projeter un plan d''action et proposer l''engagement clairement','Dire ''à bientôt peut-être''','Envoyer un SMS 3 mois plus tard','Laisser partir sans proposition','a','');
INSERT INTO quiz_questions VALUES(202,117,'Pourquoi la pesée n''est-elle pas suffisante à elle seule ?','Parce qu''elle ne distingue ni masse maigre, ni hydratation, ni répartition','Parce qu''elle est trop précise','Parce qu''elle coûte trop cher','Aucune raison, elle suffit toujours','a','');
INSERT INTO quiz_questions VALUES(203,117,'Quelle condition idéale pour une pesée fiable en impédancemétrie ?','À jeun, vessie vide, pas d''effort intense récent, hydratation stable','Juste après un repas copieux','Immédiatement après le sauna','Avec les chaussures','a','');
INSERT INTO quiz_questions VALUES(204,117,'Comment gérer un adhérent obsédé par le chiffre de la balance ?','Élargir les repères (tour de taille, photos, ressenti, performances)','Le peser chaque jour plusieurs fois','Ne jamais le peser, même au début','Critiquer ses choix alimentaires','a','');
INSERT INTO quiz_questions VALUES(205,117,'Quelle variation de poids est considérée comme normale en 24h ?','Jusqu''à 1 à 2 kg selon hydratation, repas, activité','Aucune variation possible','Jusqu''à 10 kg','1 g maximum','a','');
INSERT INTO quiz_questions VALUES(206,117,'Quelle restitution est la plus motivante pour l''adhérent ?','Mettre en avant la tendance (pas le chiffre ponctuel) et les progrès qualitatifs','Comparer défavorablement aux autres','Annoncer des objectifs irréalistes','Ne rien commenter','a','');
INSERT INTO quiz_questions VALUES(207,118,'Quelle est la contre-indication absolue de l''E-sculpt ?','Port de stimulateur cardiaque, grossesse, implants métalliques dans la zone','Cheveux courts','Hauteur supérieure à 1m70','Aucune contre-indication','a','');
INSERT INTO quiz_questions VALUES(208,118,'Quel type de stimulation délivre l''E-sculpt ?','Des contractions musculaires ciblées via technologie EMS/HIFEM','Un massage manuel','Un bain glacé','Une lumière infrarouge seule','a','');
INSERT INTO quiz_questions VALUES(209,118,'Combien de séances sont généralement nécessaires pour des résultats visibles ?','Un protocole de plusieurs séances rapprochées (ex : 4-8 séances sur quelques semaines)','Une seule séance suffit toujours','Une séance par an','Aucune séance n''est nécessaire','a','');
INSERT INTO quiz_questions VALUES(210,118,'Quel comportement côté adhérent maximise les effets de l''E-sculpt ?','Combiner l''E-sculpt avec une activité physique régulière et une alimentation équilibrée','Rester sédentaire','Manger en excès avant chaque séance','Doubler les séances en secret','a','');
INSERT INTO quiz_questions VALUES(211,118,'Quelle zone n''est PAS indiquée pour l''E-sculpt ?','Une zone avec plaie ouverte ou inflammation locale','Les cuisses saines','Les abdominaux saines','Les fessiers sains','a','');
INSERT INTO quiz_questions VALUES(212,118,'Quel réglage doit être ajusté pendant la séance ?','L''intensité, selon tolérance et ressenti de l''adhérent','La date du jour','Le volume du téléphone','La couleur de la machine','a','');
INSERT INTO quiz_questions VALUES(213,119,'Quel est le premier livrable d''un suivi spécifique ?','Un bilan initial écrit avec objectifs SMART et point de départ','Un simple SMS','Rien du tout','Un post sur les réseaux sociaux','a','');
INSERT INTO quiz_questions VALUES(214,119,'À quelle fréquence réévaluer les objectifs d''un suivi ?','Tous les 1 à 3 mois selon la dynamique, a minima à chaque cycle','Tous les 10 ans','Jamais','Chaque jour matin et soir','a','');
INSERT INTO quiz_questions VALUES(215,119,'Qu''est-ce qui différencie un suivi spécifique d''une simple séance ?','La continuité, la personnalisation et le suivi des indicateurs dans la durée','Le prix uniquement','La salle utilisée','Rien, c''est identique','a','');
INSERT INTO quiz_questions VALUES(216,119,'Quel indicateur suivre pour un objectif de réathlétisation ?','Douleur, amplitude, force et retour aux gestes du sport cible','La taille des cheveux','La météo','Aucun indicateur','a','');
INSERT INTO quiz_questions VALUES(217,119,'Quand réorienter un adhérent vers un professionnel de santé ?','Dès qu''il y a douleur persistante, pathologie ou dépassement du champ de compétence du coach','Jamais, on gère tout seul','Uniquement à la fin du contrat','Après 10 ans d''accompagnement','a','');
INSERT INTO quiz_questions VALUES(218,119,'Un bon suivi spécifique doit être :','Écrit, partagé avec l''adhérent et ajustable à chaque point d''étape','Oral, informel, et réservé au coach','Complètement identique pour tous','Caché dans un classeur fermé','a','');
INSERT INTO quiz_questions VALUES(219,125,'Quel apport protéique journalier est généralement recommandé pour un adulte sédentaire ?','Environ 0.8 à 1 g par kg de poids','5 g par kg de poids','50 g par kg de poids','Aucun apport nécessaire','a','');
INSERT INTO quiz_questions VALUES(220,125,'Quel rôle principal pour les lipides ?','Hormones, membranes cellulaires, énergie longue durée et absorption des vitamines liposolubles','Ils ne servent à rien','Seulement stocker de la graisse','Exclusivement détoxifier le foie','a','');
INSERT INTO quiz_questions VALUES(221,125,'Quelle hydratation journalière conseiller à un adulte actif ?','Environ 1.5 à 2.5 L, variable selon la sueur, la saison et le sport pratiqué','250 ml maximum','10 L obligatoires','Aucune eau','a','');
INSERT INTO quiz_questions VALUES(222,125,'Quel est l''index glycémique ?','Une mesure de la vitesse d''élévation de la glycémie après ingestion d''un aliment glucidique','Le poids d''un aliment','Le prix d''un aliment','La température d''un aliment','a','');
INSERT INTO quiz_questions VALUES(223,125,'Qu''est-ce qu''une protéine complète ?','Une protéine qui contient tous les acides aminés essentiels en quantité suffisante','Une protéine cuite longtemps','Une protéine en poudre uniquement','Une protéine chère','a','');
INSERT INTO quiz_questions VALUES(224,125,'Conseil de base pour un petit-déjeuner équilibré ?','Associer protéines, glucides complexes et lipides de qualité (avec fibres)','Un café noir uniquement','Un grand verre de soda','Un croissant seul','a','');
INSERT INTO quiz_questions VALUES(225,136,'Quel est le principal intérêt du format à 4 pour l''adhérent ?','Rapport qualité/prix, dynamique de groupe et émulation tout en gardant un suivi personnalisé','Aucun intérêt','Prix plus cher que l''individuel','Anonymat total','a','');
INSERT INTO quiz_questions VALUES(226,136,'Comment gérer 4 niveaux différents dans la même séance ?','Adapter la charge/amplitude et personnaliser les consignes pour chaque adhérent','Appliquer le même programme rigide pour tous','Se concentrer uniquement sur le plus fort','Annuler la séance','a','');
INSERT INTO quiz_questions VALUES(227,136,'Quel circuit est particulièrement adapté au coaching à 4 ?','Un circuit training en ateliers avec rotation par poste','Une démonstration unique sans rotation','Séance individuelle isolée pour chaque coach','Discussion libre sans exercice','a','');
INSERT INTO quiz_questions VALUES(228,136,'Quelle règle garantit la sécurité en petit groupe ?','Visuel permanent sur les 4 adhérents et consignes simples et claires','Sortir prendre un café','Laisser les adhérents sans surveillance','Augmenter fortement la charge pour tous','a','');
INSERT INTO quiz_questions VALUES(229,136,'Quel est le risque principal d''un coaching à 4 mal structuré ?','Perte d''attention personnalisée et dégradation de la relation/suivi','Un bénéfice trop élevé','Une sécurité accrue','Aucun risque','a','');
INSERT INTO quiz_questions VALUES(230,136,'Comment conclure une séance coaching à 4 ?','Feedback collectif rapide + mot personnel à chaque adhérent','Partir sans commentaire','Critiquer les plus faibles publiquement','Ne parler qu''au meilleur','a','');
INSERT INTO quiz_questions VALUES(231,131,'Quel phénomène osseux est accéléré à la ménopause ?','La perte de densité minérale osseuse (risque d''ostéopénie/ostéoporose)','La consolidation osseuse maximale','La croissance en hauteur','Aucun impact osseux','a','');
INSERT INTO quiz_questions VALUES(232,131,'Quel type d''entraînement protège le mieux la masse osseuse et musculaire ?','Le renforcement musculaire en charge et les impacts modérés','Uniquement le yoga doux allongé','Exclusivement la natation légère','Rester au lit','a','');
INSERT INTO quiz_questions VALUES(233,131,'Quel nutriment est particulièrement à surveiller ?','Le calcium et la vitamine D (os), ainsi que les protéines (masse musculaire)','Le sucre raffiné','L''alcool','Uniquement les friandises','a','');
INSERT INTO quiz_questions VALUES(234,131,'Bouffées de chaleur : quel impact sur l''entraînement ?','Adapter l''hydratation, le vestiaire, limiter les environnements trop chauds','Aucun impact','Augmenter la température de la salle','Arrêter tout sport définitivement','a','');
INSERT INTO quiz_questions VALUES(235,131,'Quel bénéfice mental reconnu de l''activité physique à la ménopause ?','Meilleur sommeil, humeur stabilisée et réduction du stress','Aggravation du stress','Somnolence permanente','Aucun bénéfice','a','');
INSERT INTO quiz_questions VALUES(236,131,'Comment positionner le coach face à un traitement hormonal substitutif ?','Ne pas se prononcer sur le traitement (champ médical) mais adapter la séance aux ressentis','Donner des conseils de posologie','Déconseiller tous les traitements','Imposer un arrêt du traitement','a','');
INSERT INTO quiz_questions VALUES(237,138,'Que stipule la matrice Eisenhower ?','Classer les tâches selon urgence et importance (4 quadrants)','Inventer une hiérarchie militaire','Créer un planning aléatoire','Rien de particulier','a','');
INSERT INTO quiz_questions VALUES(238,138,'Qu''est-ce que la règle des 2 minutes ?','Si une tâche prend moins de 2 min, la faire immédiatement','Prendre une pause de 2 minutes entre chaque tâche','Répondre aux mails en 2 minutes max sans exception','Tout faire en 2 minutes chrono','a','');
INSERT INTO quiz_questions VALUES(239,138,'Quel est l''effet principal du multitasking sur la performance cognitive ?','Baisse de la performance (coût de commutation) et augmentation des erreurs','Amélioration constante','Pas d''effet','Accélération du rythme cardiaque seul','a','');
INSERT INTO quiz_questions VALUES(240,138,'Qu''est-ce que le deep work selon Cal Newport ?','Des plages concentrées sans interruption sur des tâches cognitivement exigeantes','Travailler sous l''eau','Dormir sur son bureau','Écouter de la musique forte','a','');
INSERT INTO quiz_questions VALUES(241,138,'Quelle bonne pratique encadre une réunion efficace ?','Ordre du jour, durée limitée, décisionnaire désigné et relevé de décisions','Aucune règle','Pas d''ordre du jour','Uniquement des slides de 80 pages','a','');
INSERT INTO quiz_questions VALUES(242,138,'Comment protéger sa concentration au quotidien ?','Bloquer des créneaux sans notifications et regrouper les interruptions','Laisser toutes les notifications activées','Répondre à chaque mail en 30 secondes','Ouvrir 50 onglets en parallèle','a','');
INSERT INTO quiz_questions VALUES(243,150,'Quelle est la 1ère question à se poser avant de lancer un event club ?','Quel est l''objectif concret (acquisition, fidélisation, notoriété) et la cible visée ?','Quelle décoration choisir ?','Quel DJ recruter ?','Aucune question préalable','a','');
INSERT INTO quiz_questions VALUES(244,150,'Quel délai minimal recommander pour la préparation d''un event majeur ?','Plusieurs semaines avec un rétroplanning, idéalement 6 à 8 semaines','1 jour','1 heure','1 an minimum','a','');
INSERT INTO quiz_questions VALUES(245,150,'Quel KPI mesurer pour évaluer un event ''portes ouvertes'' ?','Nombre de leads, taux de transformation en séance test, puis en contrat','Nombre de ballons utilisés','Hauteur de la playlist','Aucun KPI','a','');
INSERT INTO quiz_questions VALUES(246,150,'Que faire immédiatement après un event ?','Relancer les leads, envoyer un message de remerciement et faire un post-mortem','Oublier tout le monde','Attendre 6 mois avant toute relance','Supprimer les contacts','a','');
INSERT INTO quiz_questions VALUES(247,150,'Quelle erreur ruine souvent un event ?','Absence de communication en amont et d''objectif clair','Prévoir trop de staff','Avoir un planning structuré','Offrir un rafraîchissement','a','');
INSERT INTO quiz_questions VALUES(248,150,'Quel canal privilégier pour inviter les adhérents ?','Combinaison mail + SMS + bouche-à-oreille en club + réseaux sociaux','Uniquement un fax','Uniquement une affichette cachée','Aucun canal','a','');
INSERT INTO quiz_questions VALUES(249,152,'Qu''est-ce qu''un signal faible côté adhérent ?','Un indice discret (baisse de fréquentation, changement d''humeur) annonçant un désengagement potentiel','Une réclamation écrite formelle','Un SMS automatique','Un post sur les réseaux sociaux de la marque','a','');
INSERT INTO quiz_questions VALUES(250,152,'Quel signal faible est le plus souvent sous-estimé ?','La diminution progressive de la fréquence des séances','Une inscription récente','Un achat de t-shirt','Une présence hebdomadaire stable','a','');
INSERT INTO quiz_questions VALUES(251,152,'Que faire quand on détecte un signal faible ?','Reprendre contact rapidement, écouter et proposer une solution concrète','Attendre que l''adhérent parte','Envoyer une facture supplémentaire','Rien ne faire','a','');
INSERT INTO quiz_questions VALUES(252,152,'Quel outil aide à repérer les signaux faibles de façon systématique ?','Un tableau de suivi des fréquentations et interactions, revu régulièrement','Aucun outil','Un agenda personnel caché','Un réveil','a','');
INSERT INTO quiz_questions VALUES(253,152,'Quel est le coût d''un adhérent qui part vs un conservé ?','L''acquisition coûte généralement plusieurs fois plus cher que la fidélisation','C''est exactement pareil','Garder un adhérent est plus cher','Aucun coût ni d''un côté ni de l''autre','a','');
INSERT INTO quiz_questions VALUES(254,152,'Quelle posture adopter lors d''un entretien de réengagement ?','Écouter sans juger, valider l''émotion puis co-construire un plan','Défendre agressivement le club','Minimiser les préoccupations du client','Lui faire signer immédiatement une clause','a','');
INSERT INTO quiz_questions VALUES(255,121,'Quel est le mouvement qui génère la puissance d''un direct ?','La rotation du bassin et le transfert de poids du pied arrière','La force du bras seul','Le saut vertical','Le blocage de la respiration prolongée','a','');
INSERT INTO quiz_questions VALUES(256,121,'Où frapper avec un crochet (hook) ?','Sur le côté de la cible (tempe, joue, foie) avec l''articulation fléchie','Directement dans l''axe central','Uniquement en bas du dos','Dans le vide au-dessus de la tête','a','');
INSERT INTO quiz_questions VALUES(257,121,'Pourquoi la garde haute est-elle fondamentale ?','Pour protéger le visage et permettre une parade rapide','Uniquement pour la posture esthétique','Elle empêche de respirer','Aucun intérêt','a','');
INSERT INTO quiz_questions VALUES(258,121,'Quel bénéfice cardio apporte une séance de boxe coaching ?','Travail à haute intensité intermittente améliorant VO2max et coordination','Aucun bénéfice cardiovasculaire','Seulement la force maximale','Uniquement de la souplesse','a','');
INSERT INTO quiz_questions VALUES(259,121,'Quel équipement est indispensable pour un cours de boxe en club ?','Gants, bandes (sous-gants) et éventuellement protège-dents si contact','Chaussures à talons','Un maillot de bain','Aucun équipement','a','');
INSERT INTO quiz_questions VALUES(260,121,'Quelle consigne de sécurité faut-il rappeler régulièrement ?','Pas de coup à la nuque, respecter le partenaire et maîtriser sa puissance','Frapper le plus fort possible sans s''arrêter','Éviter toute consigne de sécurité','Frapper sans gants','a','');
INSERT INTO quiz_questions VALUES(261,123,'Quelle est la structure la plus efficace pour un témoignage ?','Problème initial, solution trouvée, résultat mesurable obtenu','Uniquement parler de la météo','Décrire uniquement le coach','Une suite d''adjectifs vagues','a','');
INSERT INTO quiz_questions VALUES(262,123,'À quel moment demander un témoignage ?','Après un résultat tangible et au pic émotionnel positif de l''adhérent','Dès la première séance, avant tout résultat','Jamais','Uniquement 10 ans après','a','');
INSERT INTO quiz_questions VALUES(263,123,'Quel élément rend un témoignage crédible ?','Nom, photo/vidéo avec accord, chiffres précis et détails personnels','Aucun nom ni détail','Une signature anonyme sans contexte','Un texte publicitaire sans rapport','a','');
INSERT INTO quiz_questions VALUES(264,123,'Qu''obligatoire obtenir avant de publier un témoignage ?','Le consentement écrit explicite du client pour l''utilisation (RGPD)','Aucune autorisation','Un accord oral vague','Un accord rétroactif 10 ans après publication','a','');
INSERT INTO quiz_questions VALUES(265,123,'Quel format de témoignage est le plus impactant aujourd''hui ?','La vidéo courte authentique avant/après avec récit sincère','Une longue lettre manuscrite illisible','Un tweet anonyme','Un fax','a','');
INSERT INTO quiz_questions VALUES(266,123,'Comment relancer un client pour un témoignage sans insister ?','Proposer un cadre simple (questions ouvertes courtes) et laisser le choix du format','Envoyer 10 messages par jour','Menacer d''arrêter le suivi','Publier son témoignage sans lui dire','a','');
INSERT INTO quiz_questions VALUES(267,126,'Quels sont les principes fondamentaux du Pilates ?','Concentration, contrôle, centrage, respiration, fluidité et précision','Puissance, rapidité, cris et sueurs','Isolement total et apnée','Aucun principe','a','');
INSERT INTO quiz_questions VALUES(268,126,'Qu''appelle-t-on le ''powerhouse'' ?','Le centre du corps : transverse, plancher pelvien, multifides, diaphragme','La salle de musculation','Un type de machine','Les biceps','a','');
INSERT INTO quiz_questions VALUES(269,126,'Quelle respiration est typique du Pilates ?','Respiration thoracique latérale avec expiration sur l''effort','Apnée prolongée en tout moment','Respiration uniquement par la bouche inspirée','Aucune respiration particulière','a','');
INSERT INTO quiz_questions VALUES(270,126,'Pour qui le Pilates est-il particulièrement bénéfique ?','Toutes populations, notamment sédentaires, lombalgiques et post-partum','Uniquement des athlètes pro','Uniquement des danseurs','Personne','a','');
INSERT INTO quiz_questions VALUES(271,126,'Quelle progression pédagogique est logique en Pilates ?','Du mat (sol) vers les machines, du statique contrôlé vers le dynamique complexe','Directement les exercices les plus avancés','Uniquement des exercices statiques toute sa vie','Au hasard','a','');
INSERT INTO quiz_questions VALUES(272,126,'Quelle erreur typique chez un débutant Pilates ?','Crispation, apnée et manque d''ancrage du bassin','Trop de relâchement','Respirer trop lentement','Aucune erreur','a','');
